import dom,rs
HB='''/// 📑️ Fills one optional text field in its original slot from borrowed binary octets.
fn option_text_into(output:&mut Option<String>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(()),1=>{*output=Some(String::new());native::reader_text_into(output.as_mut().unwrap(),reader,control)},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}}
/// 📑️ Fills one optional number in its original slot from borrowed binary octets.
fn option_number_into(output:&mut Option<f64>,reader:&mut store::ByteReader<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(()),1=>{*output=Some(f64(reader)?);Ok(())},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}}
/// 📑️ Fills one binary run, inserting its optional style fields in place.
fn run_binary_into(output:&mut DocRun,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{native::reader_text_into(&mut output.text,reader,control)?;output.style.bold=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;output.style.italic=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;output.style.underline=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;option_number_into(&mut output.style.size,reader)?;option_text_into(&mut output.style.font,reader,control)?;option_text_into(&mut output.style.color,reader,control)?;option_text_into(&mut output.style.link,reader,control)}
/// 📑️ Fills a binary block list, counting its owner before its children.
pub(crate) fn blocks_binary_into(output:&mut Vec<DocBlock>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;native::binary_list_into(output,reader,control,limits,entities,Default::default,|block,reader,control,entities|block_binary_into(block,reader,control,limits,entities))}
/// 📑️ Selects each binary block variant in its retained slot before copying its text or children.
fn block_binary_into(output:&mut DocBlock,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{
0=>{*output=DocBlock::Paragraph{style_id:None,runs:Vec::new()};let DocBlock::Paragraph{style_id,runs}=&mut *output else{unreachable!()};option_text_into(style_id,reader,control)?;native::binary_list_into(runs,reader,control,limits,entities,Default::default,|run,reader,control,_|run_binary_into(run,reader,control))?;},
1=>{let level=reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;*output=DocBlock::Heading{level,style_id:None,runs:Vec::new()};let DocBlock::Heading{style_id,runs,..}=&mut *output else{unreachable!()};option_text_into(style_id,reader,control)?;native::binary_list_into(runs,reader,control,limits,entities,Default::default,|run,reader,control,_|run_binary_into(run,reader,control))?;},
2=>{let ordered=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;*output=DocBlock::List{ordered,items:Vec::new()};let DocBlock::List{items,..}=&mut *output else{unreachable!()};native::binary_list_into(items,reader,control,limits,entities,Default::default,|item,reader,control,entities|blocks_binary_into(&mut item.blocks,reader,control,limits,entities))?;},
3=>{*output=DocBlock::Table{rows:Vec::new()};let DocBlock::Table{rows}=&mut *output else{unreachable!()};native::binary_list_into(rows,reader,control,limits,entities,Default::default,|row,reader,control,entities|native::binary_list_into(&mut row.cells,reader,control,limits,entities,Default::default,|cell,reader,control,entities|blocks_binary_into(&mut cell.blocks,reader,control,limits,entities)))?;},
4=>{*output=DocBlock::Code{language:None,text:String::new()};let DocBlock::Code{language,text}=&mut *output else{unreachable!()};option_text_into(language,reader,control)?;native::reader_text_into(text,reader,control)?;},5=>{*output=DocBlock::Quote{blocks:Vec::new()};let DocBlock::Quote{blocks}=&mut *output else{unreachable!()};blocks_binary_into(blocks,reader,control,limits,entities)?;},
6=>{*output=DocBlock::Image{image_id:String::new(),alt:String::new(),width:None,height:None};let DocBlock::Image{image_id,alt,width,height}=&mut *output else{unreachable!()};native::reader_text_into(image_id,reader,control)?;native::reader_text_into(alt,reader,control)?;option_number_into(width,reader)?;option_number_into(height,reader)?;},7=>*output=DocBlock::PageBreak,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native block kind"))}Ok(())})}
'''
B='''/// 🧩️ Fills the retained document root from borrowed binary octets, inserting every style, image and block before its fields.
pub fn binary_into(output:&mut SemioDocumentSnapshot,body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Document native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;native::reader_text_into(&mut output.schema,&mut reader,control)?;
 native::binary_list_into(&mut output.styles,&mut reader,control,limits,&mut entities,Default::default,|style,reader,control,_|{native::reader_text_into(&mut style.id,reader,control)?;native::reader_text_into(&mut style.name,reader,control)?;option_text_into(&mut style.based_on,reader,control)})?;
 native::binary_list_into(&mut output.images,&mut reader,control,limits,&mut entities,Default::default,|image,reader,control,_|{native::reader_text_into(&mut image.id,reader,control)?;native::reader_text_into(&mut image.mime,reader,control)?;native::reader_bytes_into(&mut image.bytes,reader,control)})?;
 blocks_binary_into(&mut output.blocks,&mut reader,control,limits,&mut entities)?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Document native trailing bytes"))}Ok(())}
'''
HT='''/// 📑️ Fills one optional hexadecimal text field in its original slot.
fn optional_text_into(output:&mut Option<String>,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}*output=Some(String::new());native::hex_text_into(output.as_mut().unwrap(),value,control)}
/// 📑️ Fills one optional IEEE number in its original slot.
fn optional_number_into(output:&mut Option<f64>,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native optional presence"))}*output=Some(number_text(value,control)?);Ok(())}
/// 📑️ Fills one text run, inserting its optional style fields in place.
fn run_text_into(output:&mut DocRun,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{let[text,style]=native::record(value,control)?;let[bold,italic,underline,size,font,color,link]=native::record(style,control)?;native::hex_text_into(&mut output.text,text,control)?;output.style.bold=bool_text(bold)?;output.style.italic=bool_text(italic)?;output.style.underline=bool_text(underline)?;optional_number_into(&mut output.style.size,size,control)?;optional_text_into(&mut output.style.font,font,control)?;optional_text_into(&mut output.style.color,color,control)?;optional_text_into(&mut output.style.link,link,control)}
/// 📑️ Fills a text block list, counting its owner before its children.
pub fn blocks_text_into(output:&mut Vec<DocBlock>,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{native::entities(entities,1,limits)?;native::text_list_into(output,value,control,limits,entities,Default::default,|block,value,control,entities|block_text_into(block,value,control,limits,entities))}
/// 📑️ Selects each text block variant in its retained slot before copying its text or children.
pub fn block_text_into(output:&mut DocBlock,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Document native block tag missing"))?;match tag{
"P"=>{let[style_id,runs]=native::record(value,control)?;*output=DocBlock::Paragraph{style_id:None,runs:Vec::new()};let DocBlock::Paragraph{style_id:style_slot,runs:run_slot}=&mut *output else{unreachable!()};optional_text_into(style_slot,style_id,control)?;native::text_list_into(run_slot,runs,control,limits,entities,Default::default,|run,value,control,_|run_text_into(run,value,control))?;},
"H"=>{let[level,style_id,runs]=native::record(value,control)?;let level=control.scoped_stage(|control|{control.begin_stage(level.len())?;for _ in level.bytes(){control.step()?;}level.parse::<u8>().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native unsigned8 heading"))})?;*output=DocBlock::Heading{level,style_id:None,runs:Vec::new()};let DocBlock::Heading{style_id:style_slot,runs:run_slot,..}=&mut *output else{unreachable!()};optional_text_into(style_slot,style_id,control)?;native::text_list_into(run_slot,runs,control,limits,entities,Default::default,|run,value,control,_|run_text_into(run,value,control))?;},
"L"=>{let[ordered,items]=native::record(value,control)?;let ordered=bool_text(ordered)?;*output=DocBlock::List{ordered,items:Vec::new()};let DocBlock::List{items:item_slot,..}=&mut *output else{unreachable!()};native::text_list_into(item_slot,items,control,limits,entities,Default::default,|item,value,control,entities|{let[blocks]=native::record(value,control)?;blocks_text_into(&mut item.blocks,blocks,control,limits,entities)})?;},
"T"=>{let[rows]=native::record(value,control)?;*output=DocBlock::Table{rows:Vec::new()};let DocBlock::Table{rows:row_slot}=&mut *output else{unreachable!()};native::text_list_into(row_slot,rows,control,limits,entities,Default::default,|row,value,control,entities|{let[cells]=native::record(value,control)?;native::text_list_into(&mut row.cells,cells,control,limits,entities,Default::default,|cell,value,control,entities|{let[blocks]=native::record(value,control)?;blocks_text_into(&mut cell.blocks,blocks,control,limits,entities)})})?;},
"C"=>{let[language,text]=native::record(value,control)?;*output=DocBlock::Code{language:None,text:String::new()};let DocBlock::Code{language:language_slot,text:text_slot}=&mut *output else{unreachable!()};optional_text_into(language_slot,language,control)?;native::hex_text_into(text_slot,text,control)?;},
"Q"=>{let[blocks]=native::record(value,control)?;*output=DocBlock::Quote{blocks:Vec::new()};let DocBlock::Quote{blocks:block_slot}=&mut *output else{unreachable!()};blocks_text_into(block_slot,blocks,control,limits,entities)?;},
"I"=>{let[image_id,alt,width,height]=native::record(value,control)?;*output=DocBlock::Image{image_id:String::new(),alt:String::new(),width:None,height:None};let DocBlock::Image{image_id:id_slot,alt:alt_slot,width:w,height:h}=&mut *output else{unreachable!()};native::hex_text_into(id_slot,image_id,control)?;native::hex_text_into(alt_slot,alt,control)?;optional_number_into(w,width,control)?;optional_number_into(h,height,control)?;},"B"=>{let[]=native::record::<0>(value,control)?;*output=DocBlock::PageBreak;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Document native block kind"))}Ok(())})}
'''
D='''/// 📝️ Fills the retained document root from the borrowed document body, inserting every style, image and block before its fields.
pub fn document_into(output:&mut SemioDocumentSnapshot,body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","styles","images","blocks"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;native::hex_text_into(&mut output.schema,fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Document native schema missing"))?,control)?;
 native::text_list_into(&mut output.styles,fields[1].unwrap_or("[]"),control,limits,&mut entities,Default::default,|style,value,control,_|{let[id,name,based_on]=native::record(value,control)?;native::hex_text_into(&mut style.id,id,control)?;native::hex_text_into(&mut style.name,name,control)?;optional_text_into(&mut style.based_on,based_on,control)})?;
 native::text_list_into(&mut output.images,fields[2].unwrap_or("[]"),control,limits,&mut entities,Default::default,|image,value,control,_|{let[id,mime,bytes]=native::record(value,control)?;native::hex_text_into(&mut image.id,id,control)?;native::hex_text_into(&mut image.mime,mime,control)?;native::hex_bytes_into(&mut image.bytes,bytes,control)})?;
 blocks_text_into(&mut output.blocks,fields[3].unwrap_or("[]"),control,limits,&mut entities)}
'''
p=rs.native("📑️document")
print(dom.apply("📑️document",B,D,remove=("option","run_binary","blocks_binary","block_binary","optional_text","run_text","blocks_text","block_text")))
s=open(p,encoding="utf-8").read()
s=s.replace("/// 🧩️ Fills the retained document root",HB+"/// 🧩️ Fills the retained document root",1)
s=s.replace("/// 📝️ Fills the retained document root",HT+"/// 📝️ Fills the retained document root",1)
s=s.rstrip("\n")+"\n/// 🕳️ The empty typed root every native prefix starts from.\npub fn empty()->SemioDocumentSnapshot{SemioDocumentSnapshot{schema:String::new(),styles:Vec::new(),images:Vec::new(),blocks:Vec::new()}}\n"
open(p,"w",encoding="utf-8").write(s)
print(dom.fmt("📑️document"))
